class HealthBar {
    private var storedHealth = 100;

    var health {
        get { return storedHealth; }
        set (newHealth) {
            if (newHealth < 0) {
                storedHealth = 0;
            } else if (newHealth > 100) {
                storedHealth = 100;
            } else {
                storedHealth = newHealth;
            }
        }
    };
}

